```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') GROUP BY ALL",
          "claim": "search's outgoing rate.Rate/GetRates client spans take about 1.7 s p50, while geo.Geo/Nearby stays at about 0.5 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT round(min(start_gap),1) min_gap, round(approx_quantile(start_gap,0.5),1) med_gap, round(max(start_gap),1) max_gap, round(avg(end_gap),1) avg_end_gap_ms, count(*) n FROM (SELECT (epoch_ms(s.time)-epoch_ms(c.time)) start_gap, (epoch_ms(s.time)+s.duration/1e6 - epoch_ms(c.time) - c.duration/1e6) end_gap FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' AND s.service_name='rate')",
          "claim": "rate's server span starts about 1.5 s after search's client span, then runs under 1 ms; the wait is before rate receives the request."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.5)/1e6,2) p50_ms FROM normal_traces WHERE service_name='rate' AND span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "Rate's own server span is fast in the normal period too (about 1 ms p50), so rate itself is not the slow part."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY ALL",
          "claim": "Frontend's HTTP /hotels and its search.Search/Nearby client spans both rise to about 1.7 s p50, inheriting search's delay."
        }
      ]
    }
  ]
}
```

